    description: "Ніжне філе без кістки для котлет, запікання, тушкування та дитячих страв.",
    category: "Індичка з вільного вигулу",
    unit: "1 кг",
    inStock: true,
  });
  expect(ProductSchema.safeParse(products[0]).success).toBe(true);
});

